            "summary": "Link-header (RFC5988) audit feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v3/stats/summary": {
          "get": {
            "summary": "Grand reconciliation totals",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        },
        "/v2/events": {
          "get": {
            "summary": "DEPRECATED legacy feed",
            "security": [
              {
                "bearer": []
              }
            ]
          }
        }
      }
    }
  },
  "updated_at": "2026-06-30T04:47:28.206639+00:00"
}

